const rows = $json.data ?? [];

const rank = {
  CRITICAL: 2,
  WATCH: 1,
  NORMAL: 0
};

const attention = rows
  .filter(r =>
    ["WATCH", "CRITICAL"].includes(r.overall_status)
  )
  .sort((a, b) => {
    const statusDiff =
      (rank[b.overall_status] ?? 0) -
      (rank[a.overall_status] ?? 0);

    if (statusDiff !== 0) {
      return statusDiff;
    }

    return String(a.drop_point_name ?? "")
      .localeCompare(
        String(b.drop_point_name ?? "")
      );
  });


if (attention.length === 0) {
  return [
    {
      json: {
        has_alert: false,
        alert_count: 0,
        message: ""
      }
    }
  ];
}


// ============================================================
// HELPERS
// ============================================================

function money(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return "-";
  }

  return (
    "Rp" +
    Math.round(Number(value))
      .toLocaleString("id-ID")
  );
}


function pct(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return "-";
  }

  return (
    Number(value).toFixed(2) +
    "%"
  );
}


function hours(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return "-";
  }

  return Number(value).toFixed(2);
}


function num(value) {
  return Number(value ?? 0);
}


function statusIcon(status) {
  if (status === "CRITICAL") {
    return "🔴";
  }

  if (status === "WATCH") {
    return "🟠";
  }

  return "🟢";
}


function unhealthy(status) {
  return [
    "WATCH",
    "CRITICAL"
  ].includes(status);
}


// ============================================================
// BUILD DROP POINT SECTIONS
// ============================================================

const sections = attention.map(dp => {

  // ==========================================================
  // PRIORITY
  // ==========================================================

  const priorities = [];


  if (unhealthy(dp.revenue_status)) {
    priorities.push({
      status: dp.revenue_status,
      text:
        `Pendapatan: pencapaian ` +
        `${pct(dp.revenue_achievement_pct)} ` +
        `dari target ${money(dp.revenue_target)}. ` +
        `Review gap terhadap target dan ` +
        `seller penyumbang gap.`
    });
  }


  if (unhealthy(dp.seller_status)) {
    priorities.push({
      status: dp.seller_status,
      text:
        `Seller: ${num(dp.watch_seller)} watch dan ` +
        `${num(dp.critical_seller)} critical. ` +
        `Tindak lanjuti seller yang ` +
        `membutuhkan perhatian.`
    });
  }


  if (unhealthy(dp.parcel_status)) {
    priorities.push({
      status: dp.parcel_status,
      text:
        `Paket di DP: ` +
        `${num(dp.parcel_at_dp)} paket masih di DP, ` +
        `${num(dp.parcel_over_24h)} >24 jam, ` +
        `terlama ${hours(dp.oldest_parcel_hours)} jam. ` +
        `Prioritaskan paket aging tertua agar ` +
        `segera keluar ke tahap berikutnya.`
    });
  }


  if (unhealthy(dp.delivery_status)) {
    priorities.push({
      status: dp.delivery_status,
      text:
        `Pengiriman: on-time ` +
        `${pct(dp.on_time_rate_pct)} ` +
        `vs SLA ${pct(dp.delivery_sla_target_pct)}, ` +
        `${num(dp.overdue_delivery)} overdue dan ` +
        `${num(dp.failed_delivery)} gagal kirim. ` +
        `Prioritaskan shipment overdue dan ` +
        `penyebab keterlambatan.`
    });
  }


  priorities.sort(
    (a, b) =>
      (rank[b.status] ?? 0) -
      (rank[a.status] ?? 0)
  );


  // ==========================================================
  // RESPONSIBILITY
  // ==========================================================

  const responsibilities = [];


  if (
    unhealthy(dp.revenue_status) ||
    unhealthy(dp.seller_status)
  ) {
    responsibilities.push(
      `Seller / Pendapatan -> ` +
      `Unit Seller -> PIC Seller terkait`
    );
  }


  if (unhealthy(dp.parcel_status)) {
    responsibilities.push(
      `Paket (${dp.parcel_status}) -> ` +
      `Unit Outbound -> ` +
      `PIC Outbound - ${dp.drop_point_name}`
    );
  }


  if (unhealthy(dp.delivery_status)) {
    responsibilities.push(
      `Pengiriman (${dp.delivery_status}) -> ` +
      `Unit Delivery -> ` +
      `PIC Delivery - ${dp.drop_point_name}`
    );
  }


  const manager =
    dp.manager_name ?? "-";


  const returnDelivery =
    dp.return_delivery ??
    dp.returned_delivery ??
    0;


  // ==========================================================
  // MESSAGE
  // ==========================================================

  return [
    `${statusIcon(dp.overall_status)} ` +
      `${dp.drop_point_name} - ${dp.overall_status}`,

    `Manager: ${manager}`,

    "",

    "💰 Pendapatan",
    `${money(dp.revenue)} / ${money(dp.revenue_target)}`,
    `Pencapaian: ${pct(dp.revenue_achievement_pct)}`,
    `Status: ${dp.revenue_status}`,

    "",

    "🏪 Seller",
    `Aktif: ` +
      `${num(dp.active_seller)}/` +
      `${num(dp.active_seller_target)}`,
    `Watch: ${num(dp.watch_seller)} | ` +
      `Critical: ${num(dp.critical_seller)}`,
    `Status: ${dp.seller_status}`,

    "",

    "📦 Paket di DP",
    `Masuk MTD: ${num(dp.parcel_in_mtd)} | ` +
      `Keluar MTD: ${num(dp.parcel_out_mtd)}`,
    `Di DP: ${num(dp.parcel_at_dp)}`,
    `12-24 jam: ${num(dp.parcel_12_24h)} | ` +
      `>24 jam: ${num(dp.parcel_over_24h)}`,
    `Terlama: ` +
      `${hours(dp.oldest_parcel_hours)} jam`,
    `Rata-rata di DP: ` +
      `${hours(dp.avg_dp_hours)} jam`,
    `Persentase keluar: ` +
      `${pct(dp.parcel_out_pct)}`,
    `Status: ${dp.parcel_status}`,

    "",

    "🚚 Pengiriman",
    `Completed: ${num(dp.completed_delivery)} | ` +
      `In Transit: ${num(dp.in_transit_delivery)}`,
    `On Time: ${num(dp.on_time_delivery)} | ` +
      `Late: ${num(dp.late_delivery)}`,
    `Failed: ${num(dp.failed_delivery)} | ` +
      `Return: ${num(returnDelivery)} | ` +
      `Overdue: ${num(dp.overdue_delivery)}`,
    `On-time: ${pct(dp.on_time_rate_pct)} ` +
      `vs SLA ${pct(dp.delivery_sla_target_pct)}`,
    `Status: ${dp.delivery_status}`,

    "",

    "👤 Penanggung Jawab",

    ...(
      responsibilities.length
        ? responsibilities.map(
            (item, index) =>
              `${index + 1}. ${item}`
          )
        : [
            "Tidak ada area yang " +
            "membutuhkan eskalasi."
          ]
    ),

    `Eskalasi keseluruhan: ${manager}`,

    "",

    "🎯 Prioritas",

    ...(
      priorities.length
        ? priorities.map(
            (item, index) =>
              `${index + 1}. ` +
              `[${item.status}] ` +
              `${item.text}`
          )
        : [
            "Tidak ada tindakan khusus."
          ]
    )

  ].join("\n");
});


// ============================================================
// FINAL TELEGRAM MESSAGES
// ============================================================

const intro = [
  "📊 INTRADAY OPERATIONAL REPORT",
  "",
  `Drop Point perlu perhatian: ${attention.length}`
].join("\n");

const MAX_LENGTH = 3500;
const messages = [];
let current = intro;

for (const section of sections) {
  const addition = "\n\n------------------------------\n\n" + section;
  if (current.length + addition.length > MAX_LENGTH && current.length > 0) {
    messages.push(current);
    current = [
      "📊 INTRADAY OPERATIONAL REPORT - LANJUTAN",
      "",
      section
    ].join("\n");
  } else {
    current += addition;
  }
}

if (current) messages.push(current);

return messages.map((message, index) => ({
  json: {
    has_alert: true,
    alert_count: attention.length,
    message,
    part: index + 1,
    total_parts: messages.length
  }
}));
